#include "DX12Manager.h"
#include "MemoryManager.h"
#include <vector>
#include <memory>

DX12Manager::DX12Manager() {
    // Initialize memory manager
    memoryManager.Init();
}

DX12Manager::~DX12Manager() {
    // Release all resources
    if (swapChain) swapChain->Release();
    if (device) device->Release();
    if (commandQueue) commandQueue->Release();
    if (rtvHeap) rtvHeap->Release();
}

bool DX12Manager::Init(HWND hwnd) {
    // Create DXGI factory
    ComPtr<IDXGIFactory4> factory;
    DXGICreateFactory(IID_PPV_ARGS(&factory));

    // Find compatible adapter
    ComPtr<IDXGIAdapter4> adapter;
    for (UINT i = 0; factory->EnumAdapters4(i, &adapter) != DXGI_ERROR_NOT_FOUND; ++i) {
        if (adapter->CheckInterfaceSupport(IID_PPV_ARGS(&device), &DXGI_ADAPTER_FLAG_NONE) == S_OK) {
            break;
        }
    }

    // Create device
    ComPtr<ID3D12Device> tempDevice;
    adapter->GetDevice(IID_PPV_ARGS(&tempDevice));
    device = tempDevice.Get();

    // Create command queue
    D3D12_COMMAND_QUEUE_DESC queueDesc = {
        {.Type = D3D12_COMMAND_LIST_TYPE_DIRECT}
    };
    device->CreateCommandQueue(&queueDesc, IID_PPV_ARGS(&commandQueue));

    // Create swapchain
    DXGI_SWAP_CHAIN_DESC1 swapChainDesc = {
        {.BufferCount = 2,
         .Width = 1920,
         .Height = 1080,
         .Format = DXGI_FORMAT_R8G8B8A8_UNORM,
         .SampleDesc = {.Count = 1},
         .SwapEffect = DXGI_SWAP_EFFECT_FLIP_DISCARD}
    };
    factory->CreateSwapChainForHwnd(
        commandQueue.Get(),
        hwnd,
        &swapChainDesc,
        nullptr,
        nullptr,
        &swapChain
    );

    // Create RTV heap
    CD3DX12_DESCRIPTOR_HEAP_DESC rtvHeapDesc(D3D12_DESCRIPTOR_HEAP_TYPE_RTV, 2, false);
    device->CreateDescriptorHeap(&rtvHeapDesc, IID_PPV_ARGS(&rtvHeap));

    return true;
}

void DX12Manager::Render() {
    // Acquire next back buffer
    UINT backBufferIndex;
    swapChain->GetBuffer(0, IID_PPV_ARGS(&backBuffer));
    swapChain->GetCurrentBackBufferIndex(&backBufferIndex);

    // Record commands
    CD3DX12_CPU_DESCRIPTOR_HANDLE rtvHandle(rtvHeap->GetCPUDescriptorHandleForHeapStart(), backBufferIndex, rtvHeap->GetDesc().IncrementSize);
    commandList->Reset(commandAllocator, nullptr);
    commandList->ResourceBarrier(1, &CD3DX12_RESOURCE_BARRIER::Transition(backBuffer.Get(), D3D12_RESOURCE_STATE_COMMON, D3D12_RESOURCE_STATE_RENDER_TARGET));
    commandList->OMSetRenderTargets(1, &rtvHandle, false, nullptr);
    // ... (rendering code)
    commandList->Close();

    // Submit command list
    ID3D12CommandList* commandLists[] = {commandList.Get()};
    commandQueue->ExecuteCommandLists(1, commandLists);
    swapChain->Present(1, 0);
}
