MemoryManager::MemoryManager() : totalAllocated(0) {}

MemoryManager::~MemoryManager() {
    for (auto heap : heaps) {
        heap->Release();
    }
}

void MemoryManager::Init(ID3D12Device* device) {
    D3D12_HEAP_PROPERTIES heapProps = {
        {.Type = D3D12_HEAP_TYPE_DEFAULT,
         .CreationFlags = D3D12_HEAP_FLAG_NONE,
         .MemoryPool = D3D12_MEMORY_POOL_DEFAULT}
    };

    D3D12_RESOURCE_DESC resDesc = {
        {.Dimension = D3D12_RESOURCE_DIMENSION_BUFFER,
         .Width = 1024 * 1024 * 1024, // 1 GB
         .Height = 1,
         .DepthOrArraySize = 1,
         .MipLevels = 1,
         .Format = DXGI_FORMAT_UNKNOWN,
         .Flags = D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS}
    };

    device->CreateCommittedResource(&heapProps, D3D12_HEAP_FLAG_NONE, &resDesc, D3D12_RESOURCE_STATE_COMMON, nullptr, IID_PPV_ARGS(&heaps.push_back()));
}

